KIND = "questions"
SYSTEM = "articular"
E = {}


def T(id, en, fr, de, es):
    E[id] = {"en": list(en), "fr": list(fr), "de": list(de), "es": list(es)}


T("ar-c413ead3",
  ("What is the respiratory movement of the lower ribs that increases the transverse diameter of the chest called?", ["Hinge movement", "Pump-handle movement", "Caliper movement", "Bucket-handle movement", "Gliding movement"],
   "The lower ribs rise upwards and outwards at their middle like a bucket handle and increase the transverse diameter. The pump-handle movement of the upper ribs increases the anteroposterior diameter."),
  ("Comment appelle-t-on le mouvement respiratoire des côtes inférieures qui augmente le diamètre transversal du thorax ?", ["Mouvement en charnière", "Mouvement en bras de pompe", "Mouvement en compas", "Mouvement en anse de seau", "Mouvement de glissement"],
   "Les côtes inférieures s'élèvent en dehors par leur partie moyenne comme une anse de seau et augmentent le diamètre transversal. Le mouvement en bras de pompe des côtes supérieures augmente le diamètre antéro-postérieur."),
  ("Wie heißt die Atembewegung der unteren Rippen, die den Querdurchmesser des Brustkorbs vergrößert?", ["Scharnierbewegung", "Pumpenschwengelbewegung", "Zirkelbewegung", "Eimerhenkelbewegung", "Gleitbewegung"],
   "Die unteren Rippen heben sich in ihrer Mitte nach oben außen wie ein Eimerhenkel und vergrößern den Querdurchmesser. Die Pumpenschwengelbewegung der oberen Rippen vergrößert den Sagittaldurchmesser."),
  ("¿Cómo se llama el movimiento respiratorio de las costillas inferiores que aumenta el diámetro transversal del tórax?", ["Movimiento en bisagra", "Movimiento en brazo de bomba", "Movimiento en compás", "Movimiento en asa de cubo", "Movimiento de deslizamiento"],
   "Las costillas inferiores se elevan hacia arriba y afuera por su parte media como el asa de un cubo y aumentan el diámetro transversal. El movimiento en brazo de bomba de las superiores aumenta el diámetro anteroposterior."))

T("ar-185a3978",
  ("Which of the following ribs does NOT articulate with a transverse process (costotransverse joint)?", ["12th rib", "7th rib", "5th rib", "1st rib", "10th rib"],
   "The costotransverse joint lies between the tubercle of the rib and the transverse process. The 11th and 12th ribs have no tubercle and do not form this joint."),
  ("Laquelle de ces côtes ne s'articule PAS avec un processus transverse (articulation costo-transversaire) ?", ["12e côte", "7e côte", "5e côte", "1re côte", "10e côte"],
   "L'articulation costo-transversaire unit le tubercule costal au processus transverse. Les 11e et 12e côtes n'ont pas de tubercule et ne forment pas cette articulation."),
  ("Welche dieser Rippen bildet KEIN Gelenk mit einem Querfortsatz (Art. costotransversaria)?", ["12. Rippe", "7. Rippe", "5. Rippe", "1. Rippe", "10. Rippe"],
   "Das Kostotransversalgelenk liegt zwischen Rippenhöcker und Querfortsatz. Die 11. und 12. Rippe haben keinen Höcker und bilden dieses Gelenk nicht."),
  ("¿Cuál de estas costillas NO se articula con una apófisis transversa (articulación costotransversa)?", ["12.ª costilla", "7.ª costilla", "5.ª costilla", "1.ª costilla", "10.ª costilla"],
   "La articulación costotransversa está entre el tubérculo costal y la apófisis transversa. Las costillas 11.ª y 12.ª no tienen tubérculo y no forman esta articulación."))

T("ar-25e330cf",
  ("Which movement increases the anteroposterior diameter of the pelvic outlet during childbirth?", ["Fusion of the pubic symphysis", "Inward rotation of the ilium", "Widening of the acetabulum", "Forward tilting of the sacrum", "Backward movement of the coccyx"],
   "The sacrococcygeal joint lets the coccyx move backwards during childbirth, increasing the anteroposterior diameter of the pelvic outlet by a few centimetres."),
  ("Quel mouvement augmente le diamètre antéro-postérieur du détroit inférieur lors de l'accouchement ?", ["Soudure de la symphyse pubienne", "Rotation interne de l'ilium", "Élargissement de l'acétabulum", "Bascule antérieure du sacrum", "Recul du coccyx (rétropulsion)"],
   "L'articulation sacro-coccygienne permet au coccyx de reculer pendant l'accouchement, augmentant de quelques centimètres le diamètre antéro-postérieur du détroit inférieur."),
  ("Welche Bewegung vergrößert bei der Geburt den Sagittaldurchmesser des Beckenausgangs?", ["Verknöcherung der Schambeinfuge", "Innenrotation des Darmbeins", "Erweiterung der Hüftpfanne", "Vorkippen des Kreuzbeins", "Zurückweichen des Steißbeins"],
   "Das Sakrokokzygealgelenk erlaubt dem Steißbein bei der Geburt nach hinten auszuweichen; der Sagittaldurchmesser des Beckenausgangs nimmt um einige Zentimeter zu."),
  ("¿Qué movimiento aumenta el diámetro anteroposterior del estrecho inferior durante el parto?", ["Fusión de la sínfisis del pubis", "Rotación interna del ilion", "Ensanchamiento del acetábulo", "Inclinación anterior del sacro", "Desplazamiento posterior del cóccix"],
   "La articulación sacrococcígea permite que el cóccix se desplace hacia atrás durante el parto, aumentando unos centímetros el diámetro anteroposterior del estrecho inferior."))

T("ar-632188f8",
  ("Which ligament mainly provides stability of the sternoclavicular joint?", ["Interclavicular ligament", "Costoclavicular ligament", "Acromioclavicular ligament", "Coracoclavicular ligament", "Anterior sternoclavicular ligament"],
   "The costoclavicular ligament, joining the medial end of the clavicle to the first costal cartilage, is the strongest stabiliser of the joint and limits elevation of the clavicle."),
  ("Quel ligament assure principalement la stabilité de l'articulation sterno-claviculaire ?", ["Ligament interclaviculaire", "Ligament costo-claviculaire", "Ligament acromio-claviculaire", "Ligament coraco-claviculaire", "Ligament sterno-claviculaire antérieur"],
   "Le ligament costo-claviculaire, qui unit l'extrémité médiale de la clavicule au 1er cartilage costal, est le stabilisateur le plus puissant de l'articulation et limite l'élévation de la clavicule."),
  ("Welches Band sichert hauptsächlich das Sternoklavikulargelenk?", ["Lig. interclaviculare", "Lig. costoclaviculare", "Lig. acromioclaviculare", "Lig. coracoclaviculare", "Lig. sternoclaviculare anterius"],
   "Das Lig. costoclaviculare zwischen medialem Klavikulaende und 1. Rippenknorpel ist der stärkste Stabilisator des Gelenks und begrenzt das Anheben der Klavikula."),
  ("¿Qué ligamento proporciona principalmente la estabilidad de la articulación esternoclavicular?", ["Ligamento interclavicular", "Ligamento costoclavicular", "Ligamento acromioclavicular", "Ligamento coracoclavicular", "Ligamento esternoclavicular anterior"],
   "El ligamento costoclavicular, que une el extremo medial de la clavícula al primer cartílago costal, es el estabilizador más potente de la articulación y limita la elevación de la clavícula."))

T("ar-d9375ce7",
  ("Which structures form the coracoacromial arch?", ["Acromion, clavicle and spine of the scapula", "Greater tubercle, lesser tubercle and transverse humeral ligament", "Coracoid process, clavicle and 1st rib", "Glenoid cavity, labrum and acromion", "Acromion, coracoacromial ligament and coracoid process"],
   "The coracoacromial arch forms a protective roof over the humeral head; the supraspinatus tendon and subacromial bursa pass beneath it. Impingement syndrome occurs under this arch."),
  ("Quelles structures forment la voûte coraco-acromiale ?", ["Acromion, clavicule et épine de la scapula", "Tubercule majeur, tubercule mineur et ligament huméral transverse", "Processus coracoïde, clavicule et 1re côte", "Cavité glénoïdale, labrum et acromion", "Acromion, ligament coraco-acromial et processus coracoïde"],
   "La voûte coraco-acromiale forme un toit protecteur au-dessus de la tête humérale ; le tendon du supra-épineux et la bourse subacromiale passent dessous. Le conflit sous-acromial se produit sous cette voûte."),
  ("Welche Strukturen bilden das Schulterdach (Fornix humeri)?", ["Akromion, Klavikula und Spina scapulae", "Tuberculum majus, Tuberculum minus und Lig. transversum humeri", "Processus coracoideus, Klavikula und 1. Rippe", "Cavitas glenoidalis, Labrum und Akromion", "Akromion, Lig. coracoacromiale und Processus coracoideus"],
   "Das Schulterdach bildet ein schützendes Dach über dem Humeruskopf; darunter ziehen Supraspinatussehne und Bursa subacromialis. Das Impingement-Syndrom entsteht unter diesem Bogen."),
  ("¿Qué estructuras forman el arco coracoacromial?", ["Acromion, clavícula y espina de la escápula", "Tubérculo mayor, tubérculo menor y ligamento humeral transverso", "Apófisis coracoides, clavícula y 1.ª costilla", "Cavidad glenoidea, rodete y acromion", "Acromion, ligamento coracoacromial y apófisis coracoides"],
   "El arco coracoacromial forma un techo protector sobre la cabeza humeral; bajo él pasan el tendón del supraespinoso y la bolsa subacromial. El síndrome de pinzamiento se produce bajo este arco."))

T("ar-9da426c2",
  ("Which ligament holds the tendon of the long head of biceps in the intertubercular groove?", ["Coracoacromial ligament", "Coracohumeral ligament", "Transverse humeral ligament", "Superior transverse scapular ligament", "Superior glenohumeral ligament"],
   "The transverse humeral ligament spans the greater and lesser tubercles and turns the groove into a canal. If it tears, the tendon can slip out of the groove with a painful click."),
  ("Quel ligament maintient le tendon du long chef du biceps dans le sillon intertuberculaire ?", ["Ligament coraco-acromial", "Ligament coraco-huméral", "Ligament huméral transverse", "Ligament transverse supérieur de la scapula", "Ligament gléno-huméral supérieur"],
   "Le ligament huméral transverse tendu entre les tubercules majeur et mineur transforme le sillon en canal. S'il se rompt, le tendon peut sortir du sillon avec un ressaut douloureux."),
  ("Welches Band hält die Sehne des langen Bizepskopfes im Sulcus intertubercularis?", ["Lig. coracoacromiale", "Lig. coracohumerale", "Lig. transversum humeri", "Lig. transversum scapulae superius", "Lig. glenohumerale superius"],
   "Das Lig. transversum humeri überbrückt Tuberculum majus und minus und macht die Rinne zum Kanal. Reißt es, kann die Sehne mit schmerzhaftem Schnappen aus der Rinne luxieren."),
  ("¿Qué ligamento mantiene el tendón de la porción larga del bíceps en la corredera bicipital?", ["Ligamento coracoacromial", "Ligamento coracohumeral", "Ligamento humeral transverso", "Ligamento transverso superior de la escápula", "Ligamento glenohumeral superior"],
   "El ligamento humeral transverso se extiende entre los tubérculos mayor y menor y convierte la corredera en un canal. Si se rompe, el tendón puede salirse de la corredera con un chasquido doloroso."))

T("ar-d525aa5a",
  ("What is the anteroinferior labral tear that is the main cause of recurrent anterior shoulder dislocation called?", ["SLAP lesion", "Stener lesion", "Bankart lesion", "Hill–Sachs lesion", "Bennett lesion"],
   "A Bankart lesion is detachment of the anteroinferior labrum and inferior glenohumeral ligament from the glenoid. Hill–Sachs is an impaction fracture of the posterolateral humeral head; SLAP is a superior labral tear."),
  ("Comment appelle-t-on la désinsertion du labrum antéro-inférieur, principale cause des luxations antérieures récidivantes de l'épaule ?", ["Lésion SLAP", "Lésion de Stener", "Lésion de Bankart", "Encoche de Hill-Sachs", "Lésion de Bennett"],
   "La lésion de Bankart est la désinsertion du labrum antéro-inférieur et du ligament gléno-huméral inférieur de la glène. Hill-Sachs est une fracture-impaction postéro-latérale de la tête humérale ; SLAP est une lésion du labrum supérieur."),
  ("Wie heißt der anteroinferiore Labrumabriss, der Hauptursache rezidivierender vorderer Schulterluxationen ist?", ["SLAP-Läsion", "Stener-Läsion", "Bankart-Läsion", "Hill-Sachs-Läsion", "Bennett-Läsion"],
   "Die Bankart-Läsion ist der Abriss von anteroinferiorem Labrum und unterem glenohumeralem Band vom Glenoid. Hill-Sachs ist eine Impressionsfraktur des posterolateralen Humeruskopfes; SLAP ein oberer Labrumriss."),
  ("¿Cómo se llama la desinserción del rodete anteroinferior, principal causa de la luxación anterior recidivante del hombro?", ["Lesión SLAP", "Lesión de Stener", "Lesión de Bankart", "Lesión de Hill-Sachs", "Lesión de Bennett"],
   "La lesión de Bankart es la desinserción del rodete anteroinferior y del ligamento glenohumeral inferior de la glena. Hill-Sachs es una fractura por impactación posterolateral de la cabeza humeral; SLAP es una rotura del rodete superior."))

T("ar-ecd485e2",
  ("Which part of the labrum does a SLAP lesion involve?", ["The superior labrum (where the long head of biceps attaches)", "The posteroinferior labrum", "The acetabular labrum", "The whole labrum", "The anteroinferior labrum"],
   "A SLAP (Superior Labrum Anterior to Posterior) lesion is a front-to-back tear of the superior labrum where the long head of biceps attaches; it is common in throwing sports."),
  ("Quelle partie du labrum une lésion SLAP touche-t-elle ?", ["Le labrum supérieur (insertion du long chef du biceps)", "Le labrum postéro-inférieur", "Le labrum acétabulaire", "Tout le labrum", "Le labrum antéro-inférieur"],
   "La lésion SLAP (Superior Labrum Anterior to Posterior) est une déchirure d'avant en arrière du labrum supérieur, là où s'insère le long chef du biceps ; elle est fréquente dans les sports de lancer."),
  ("Welchen Teil des Labrums betrifft eine SLAP-Läsion?", ["Das obere Labrum (Ansatz des langen Bizepskopfes)", "Das posteroinferiore Labrum", "Das Labrum acetabuli", "Das gesamte Labrum", "Das anteroinferiore Labrum"],
   "Die SLAP-Läsion (Superior Labrum Anterior to Posterior) ist ein Riss des oberen Labrums am Ansatz des langen Bizepskopfes von vorn nach hinten; häufig bei Wurfsportarten."),
  ("¿Qué parte del rodete afecta una lesión SLAP?", ["El rodete superior (inserción de la porción larga del bíceps)", "El rodete posteroinferior", "El rodete acetabular", "Todo el rodete", "El rodete anteroinferior"],
   "La lesión SLAP (Superior Labrum Anterior to Posterior) es una rotura de delante atrás del rodete superior, donde se inserta la porción larga del bíceps; es frecuente en deportes de lanzamiento."))

T("ar-cfe7c2cc",
  ("Which is the most important structure for valgus stability of the elbow?", ["Quadrate ligament", "Anterior band of the ulnar collateral ligament", "Annular ligament of the radius", "Oblique cord", "Radial collateral ligament"],
   "The anterior band of the medial (ulnar) collateral ligament protects the elbow against valgus force. In throwing athletes a tear of this band is reconstructed with a tendon graft ('Tommy John' surgery)."),
  ("Quelle est la structure la plus importante pour la stabilité en valgus du coude ?", ["Ligament carré", "Faisceau antérieur du ligament collatéral ulnaire", "Ligament annulaire du radius", "Corde oblique", "Ligament collatéral radial"],
   "Le faisceau antérieur du ligament collatéral médial (ulnaire) protège le coude contre les contraintes en valgus. Chez les lanceurs, sa rupture est reconstruite par greffe tendineuse (opération de « Tommy John »)."),
  ("Welche Struktur ist für die Valgusstabilität des Ellenbogens am wichtigsten?", ["Lig. quadratum", "Vorderes Bündel des Lig. collaterale ulnare", "Lig. anulare radii", "Chorda obliqua", "Lig. collaterale radiale"],
   "Das vordere Bündel des medialen (ulnaren) Kollateralbandes schützt den Ellenbogen gegen Valguskräfte. Bei Werfern wird sein Riss mit einem Sehnentransplantat ersetzt („Tommy-John“-Operation)."),
  ("¿Cuál es la estructura más importante para la estabilidad en valgo del codo?", ["Ligamento cuadrado", "Fascículo anterior del ligamento colateral cubital", "Ligamento anular del radio", "Cuerda oblicua", "Ligamento colateral radial"],
   "El fascículo anterior del ligamento colateral medial (cubital) protege el codo frente a fuerzas en valgo. En lanzadores su rotura se reconstruye con injerto tendinoso (cirugía de «Tommy John»)."))

T("ar-9da28623",
  ("What is the ligament tear that most often causes wrist instability, and its radiographic sign?", ["Pisohamate ligament – fracture of the hook of hamate", "Ulnar collateral ligament – dislocation of the ulnar head", "Radial collateral ligament – fracture of the radial styloid", "Lunotriquetral ligament – dorsal rotation of the lunate", "Scapholunate ligament – gap wider than 3 mm between scaphoid and lunate"],
   "In a scapholunate ligament tear the AP radiograph shows a gap between the two bones (Terry Thomas sign) and a ring sign of the scaphoid; untreated, it leads to DISI deformity and SLAC arthritis."),
  ("Quelle rupture ligamentaire cause le plus souvent une instabilité du poignet, et quel est son signe radiographique ?", ["Ligament piso-hamatum – fracture de l'hamulus", "Ligament collatéral ulnaire – luxation de la tête ulnaire", "Ligament collatéral radial – fracture de la styloïde radiale", "Ligament luno-triquétral – rotation dorsale du lunatum", "Ligament scapho-lunaire – diastasis de plus de 3 mm entre scaphoïde et lunatum"],
   "Dans la rupture scapho-lunaire, la radiographie de face montre un diastasis entre les deux os (signe de Terry Thomas) et un signe de l'anneau du scaphoïde ; non traitée, elle évolue vers une déformation DISI et une arthrose SLAC."),
  ("Welcher Bandriss verursacht am häufigsten eine Handgelenksinstabilität, und welches Röntgenzeichen zeigt er?", ["Lig. pisohamatum – Fraktur des Hamulus", "Ulnares Kollateralband – Luxation des Ulnakopfes", "Radiales Kollateralband – Fraktur des Processus styloideus radii", "Lunotriquetrales Band – dorsale Kippung des Lunatum", "Skapholunäres Band – Spalt über 3 mm zwischen Scaphoid und Lunatum"],
   "Beim skapholunären Bandriss zeigt das a.-p.-Röntgenbild einen Spalt zwischen beiden Knochen (Terry-Thomas-Zeichen) und ein Ringzeichen des Scaphoids; unbehandelt folgen DISI-Fehlstellung und SLAC-Arthrose."),
  ("¿Qué rotura ligamentosa causa con más frecuencia inestabilidad de la muñeca, y cuál es su signo radiológico?", ["Ligamento pisoganchoso – fractura del gancho del ganchoso", "Ligamento colateral cubital – luxación de la cabeza del cúbito", "Ligamento colateral radial – fractura de la estiloides radial", "Ligamento lunopiramidal – rotación dorsal del semilunar", "Ligamento escafolunar – separación mayor de 3 mm entre escafoides y semilunar"],
   "En la rotura escafolunar la radiografía AP muestra una separación entre ambos huesos (signo de Terry Thomas) y el signo del anillo del escafoides; sin tratamiento evoluciona a deformidad DISI y artrosis SLAC."))

T("ar-3707eab2",
  ("What is osteoarthritis of the carpometacarpal joint of the thumb called?", ["Rhizarthrosis", "Kienböck disease", "De Quervain tenosynovitis", "Heberden node", "Dupuytren contracture"],
   "Rhizarthrosis is osteoarthritis of the saddle joint between the trapezium and the 1st metacarpal; it causes pain on gripping and turning a key, especially in postmenopausal women."),
  ("Comment appelle-t-on l'arthrose de l'articulation carpo-métacarpienne du pouce ?", ["Rhizarthrose", "Maladie de Kienböck", "Ténosynovite de De Quervain", "Nodosité d'Heberden", "Maladie de Dupuytren"],
   "La rhizarthrose est l'arthrose de l'articulation en selle entre le trapèze et le 1er métacarpien ; elle provoque des douleurs à la prise et en tournant une clé, surtout chez la femme ménopausée."),
  ("Wie heißt die Arthrose des Daumensattelgelenks?", ["Rhizarthrose", "Morbus Kienböck", "Tendovaginitis de Quervain", "Heberden-Knoten", "Dupuytren-Kontraktur"],
   "Die Rhizarthrose ist die Arthrose des Sattelgelenks zwischen Trapezium und 1. Mittelhandknochen; sie schmerzt beim Greifen und Schlüsseldrehen, vor allem bei Frauen nach der Menopause."),
  ("¿Cómo se llama la artrosis de la articulación carpometacarpiana del pulgar?", ["Rizartrosis", "Enfermedad de Kienböck", "Tenosinovitis de De Quervain", "Nódulo de Heberden", "Contractura de Dupuytren"],
   "La rizartrosis es la artrosis de la articulación en silla de montar entre el trapecio y el 1.er metacarpiano; produce dolor al agarrar y al girar una llave, sobre todo en mujeres posmenopáusicas."))

T("ar-a495b9af",
  ("If the hand is to be splinted for a long time, why are the MCP joints kept in flexion?", ["Tendons are better nourished in flexion.", "Nerves are freed from pressure in flexion.", "Bones do not unite in extension.", "The collateral ligaments are taut in flexion, so they do not shorten and cause stiffness.", "The volar plate relaxes and heals in flexion."],
   "Because of the cam shape of the metacarpal head, the MCP collateral ligaments are taut in flexion. If the joint is held in extension for long, the slack ligaments shorten and a permanent extension contracture develops."),
  ("Si la main doit être immobilisée longtemps, pourquoi place-t-on les MCP en flexion ?", ["Les tendons sont mieux nourris en flexion.", "Les nerfs sont libérés de toute compression en flexion.", "Les os ne consolident pas en extension.", "Les ligaments collatéraux sont tendus en flexion et ne se rétractent donc pas.", "La plaque palmaire se relâche et cicatrise en flexion."],
   "En raison de la forme en came de la tête métacarpienne, les ligaments collatéraux des MCP sont tendus en flexion. Si l'articulation reste longtemps en extension, les ligaments détendus se rétractent et une raideur en extension s'installe."),
  ("Warum werden die MCP-Gelenke bei längerer Ruhigstellung der Hand in Beugung gelagert?", ["In Beugung werden die Sehnen besser ernährt.", "In Beugung werden die Nerven entlastet.", "In Streckung heilen die Knochen nicht.", "Die Kollateralbänder sind in Beugung gespannt und schrumpfen daher nicht.", "In Beugung entspannt sich die palmare Platte und heilt."],
   "Wegen der Nockenform des Metakarpalkopfes sind die MCP-Kollateralbänder in Beugung gespannt. Wird das Gelenk lange gestreckt gehalten, schrumpfen die entspannten Bänder und es entsteht eine bleibende Streckkontraktur (Intrinsic-plus-Stellung)."),
  ("Si la mano debe inmovilizarse mucho tiempo, ¿por qué se mantienen las MCF en flexión?", ["En flexión los tendones se nutren mejor.", "En flexión los nervios quedan libres de compresión.", "En extensión los huesos no consolidan.", "Los ligamentos colaterales están tensos en flexión y así no se retraen.", "En flexión la placa volar se relaja y cicatriza."],
   "Por la forma de leva de la cabeza del metacarpiano, los colaterales de las MCF están tensos en flexión. Si la articulación se mantiene mucho tiempo en extensión, los ligamentos laxos se retraen y aparece una rigidez en extensión permanente."))

T("ar-9d4ca42d",
  ("Skier's thumb (gamekeeper's thumb) is an injury of which ligament?", ["Volar plate of the thumb IP joint", "Ulnar collateral ligament of the thumb MCP joint", "Scapholunate ligament", "Radial collateral ligament of the thumb MCP joint", "Anterior oblique ligament of the thumb CMC joint"],
   "Forced abduction of the thumb when falling onto a ski pole tears the ulnar collateral ligament of the MCP joint; grip and pinch strength are reduced."),
  ("Le pouce du skieur (pouce du garde-chasse) est une lésion de quel ligament ?", ["Plaque palmaire de l'IP du pouce", "Ligament collatéral ulnaire de la MCP du pouce", "Ligament scapho-lunaire", "Ligament collatéral radial de la MCP du pouce", "Ligament oblique antérieur de la TM du pouce"],
   "L'abduction forcée du pouce lors d'une chute sur le bâton de ski rompt le ligament collatéral ulnaire de la MCP ; la force de prise et de pince diminue."),
  ("Der Skidaumen ist eine Verletzung welches Bandes?", ["Palmare Platte des Daumen-IP-Gelenks", "Ulnares Kollateralband des Daumengrundgelenks", "Skapholunäres Band", "Radiales Kollateralband des Daumengrundgelenks", "Vorderes schräges Band des Daumensattelgelenks"],
   "Die gewaltsame Abduktion des Daumens beim Sturz auf den Skistock zerreißt das ulnare Kollateralband des Grundgelenks; Greif- und Spitzgriffkraft nehmen ab."),
  ("El pulgar del esquiador (pulgar del guardabosques) es una lesión de ¿qué ligamento?", ["Placa volar de la IF del pulgar", "Ligamento colateral cubital de la MCF del pulgar", "Ligamento escafolunar", "Ligamento colateral radial de la MCF del pulgar", "Ligamento oblicuo anterior de la CMC del pulgar"],
   "La abducción forzada del pulgar al caer sobre el bastón de esquí rompe el ligamento colateral cubital de la MCF; disminuye la fuerza de agarre y de pinza."))

T("ar-d07b4763",
  ("Which structure prevents hyperextension at the PIP joints of the fingers?", ["Extensor expansion", "Collateral ligaments", "Deep transverse metacarpal ligament", "Volar plate", "Lumbrical muscles"],
   "The volar plate is a thick fibrocartilaginous plate on the palmar side of the joint and limits hyperextension. Its avulsion in a hyperextension injury can lead to a swan-neck deformity."),
  ("Quelle structure empêche l'hyperextension des IPP des doigts ?", ["Appareil extenseur", "Ligaments collatéraux", "Ligament métacarpien transverse profond", "Plaque palmaire", "Muscles lombricaux"],
   "La plaque palmaire est une lame fibrocartilagineuse épaisse à la face palmaire de l'articulation qui limite l'hyperextension. Son arrachement lors d'un traumatisme en hyperextension peut donner une déformation en col de cygne."),
  ("Welche Struktur verhindert die Überstreckung der PIP-Gelenke der Finger?", ["Streckaponeurose", "Kollateralbänder", "Lig. metacarpale transversum profundum", "Palmare Platte", "Mm. lumbricales"],
   "Die palmare Platte ist eine dicke faserknorpelige Platte an der Beugeseite des Gelenks und begrenzt die Überstreckung. Ihr Ausriss bei Hyperextensionsverletzung kann zur Schwanenhalsdeformität führen."),
  ("¿Qué estructura impide la hiperextensión de las IFP de los dedos?", ["Aparato extensor", "Ligamentos colaterales", "Ligamento metacarpiano transverso profundo", "Placa volar", "Músculos lumbricales"],
   "La placa volar es una lámina fibrocartilaginosa gruesa en la cara palmar de la articulación que limita la hiperextensión. Su avulsión en una lesión por hiperextensión puede producir una deformidad en cuello de cisne."))

T("ar-b68b4630",
  ("Which ligament prevents excessive abduction of the hip joint?", ["Ligament of the head of the femur", "Ischiofemoral ligament", "Transverse acetabular ligament", "Iliofemoral ligament", "Pubofemoral ligament"],
   "The pubofemoral ligament runs from the superior pubic ramus to the inferior-anterior capsule and limits excessive abduction. The iliofemoral ligament prevents hyperextension, the ischiofemoral excessive internal rotation."),
  ("Quel ligament empêche l'abduction excessive de la hanche ?", ["Ligament de la tête fémorale", "Ligament ischio-fémoral", "Ligament transverse de l'acétabulum", "Ligament ilio-fémoral", "Ligament pubo-fémoral"],
   "Le ligament pubo-fémoral va de la branche supérieure du pubis à la partie antéro-inférieure de la capsule et limite l'abduction excessive. L'ilio-fémoral empêche l'hyperextension, l'ischio-fémoral la rotation médiale excessive."),
  ("Welches Band verhindert eine übermäßige Abduktion im Hüftgelenk?", ["Lig. capitis femoris", "Lig. ischiofemorale", "Lig. transversum acetabuli", "Lig. iliofemorale", "Lig. pubofemorale"],
   "Das Lig. pubofemorale zieht vom oberen Schambeinast zum vorderen unteren Kapselanteil und begrenzt die Abduktion. Das Lig. iliofemorale verhindert die Überstreckung, das Lig. ischiofemorale die übermäßige Innenrotation."),
  ("¿Qué ligamento impide la abducción excesiva de la cadera?", ["Ligamento de la cabeza del fémur", "Ligamento isquiofemoral", "Ligamento transverso del acetábulo", "Ligamento iliofemoral", "Ligamento pubofemoral"],
   "El ligamento pubofemoral va de la rama superior del pubis a la parte anteroinferior de la cápsula y limita la abducción excesiva. El iliofemoral impide la hiperextensión y el isquiofemoral la rotación interna excesiva."))

T("ar-7cb7465b",
  ("The oblique popliteal ligament is an expansion of the tendon of which muscle?", ["Biceps femoris", "Gastrocnemius", "Popliteus", "Semitendinosus", "Semimembranosus"],
   "The oblique popliteal ligament runs upwards and laterally from the semimembranosus tendon and reinforces the posterior knee capsule; it lies just in front of the popliteal artery."),
  ("Le ligament poplité oblique est une expansion du tendon de quel muscle ?", ["Biceps fémoral", "Gastrocnémien", "Poplité", "Semi-tendineux", "Semi-membraneux"],
   "Le ligament poplité oblique part du tendon du semi-membraneux en haut et en dehors et renforce la face postérieure de la capsule du genou ; il est juste en avant de l'artère poplitée."),
  ("Das Lig. popliteum obliquum ist eine Ausstrahlung der Sehne welches Muskels?", ["M. biceps femoris", "M. gastrocnemius", "M. popliteus", "M. semitendinosus", "M. semimembranosus"],
   "Das Lig. popliteum obliquum zieht von der Semimembranosussehne nach oben außen und verstärkt die hintere Kniegelenkkapsel; es liegt unmittelbar vor der A. poplitea."),
  ("El ligamento poplíteo oblicuo es una expansión del tendón de ¿qué músculo?", ["Bíceps femoral", "Gastrocnemio", "Poplíteo", "Semitendinoso", "Semimembranoso"],
   "El ligamento poplíteo oblicuo sale del tendón del semimembranoso hacia arriba y afuera y refuerza la cara posterior de la cápsula de la rodilla; está justo delante de la arteria poplítea."))

T("ar-02199c01",
  ("Which tendon passes between the lateral (fibular) collateral ligament and the lateral meniscus of the knee?", ["Popliteus tendon", "Tendon of the lateral head of gastrocnemius", "Plantaris tendon", "Iliotibial tract", "Biceps femoris tendon"],
   "The lateral collateral ligament is separate from the capsule and the lateral meniscus, and the popliteus tendon passes between them. The lateral meniscus is therefore more mobile and tears less often than the medial one."),
  ("Quel tendon passe entre le ligament collatéral fibulaire et le ménisque latéral du genou ?", ["Tendon du poplité", "Tendon du chef latéral du gastrocnémien", "Tendon du plantaire", "Bandelette ilio-tibiale", "Tendon du biceps fémoral"],
   "Le ligament collatéral fibulaire est séparé de la capsule et du ménisque latéral ; le tendon du poplité passe entre eux. Le ménisque latéral est donc plus mobile et se rompt moins souvent que le médial."),
  ("Welche Sehne verläuft zwischen dem lateralen (fibularen) Kollateralband und dem Außenmeniskus?", ["Popliteussehne", "Sehne des lateralen Gastrocnemiuskopfes", "Plantarissehne", "Tractus iliotibialis", "Bizeps-femoris-Sehne"],
   "Das Außenband ist von Kapsel und Außenmeniskus getrennt; zwischen ihnen zieht die Popliteussehne. Deshalb ist der Außenmeniskus beweglicher und reißt seltener als der Innenmeniskus."),
  ("¿Qué tendón pasa entre el ligamento colateral peroneo y el menisco lateral de la rodilla?", ["Tendón del poplíteo", "Tendón de la cabeza lateral del gastrocnemio", "Tendón del plantar", "Cintilla iliotibial", "Tendón del bíceps femoral"],
   "El colateral peroneo está separado de la cápsula y del menisco lateral, y entre ellos pasa el tendón del poplíteo. Por eso el menisco lateral es más móvil y se rompe menos que el medial."))

T("ar-2725a1ee",
  ("Which lateral ankle ligament is the strongest and tears least often?", ["Bifurcate ligament", "Posterior talofibular ligament", "Anterior talofibular ligament", "Calcaneofibular ligament", "Anterior tibiofibular ligament"],
   "The lateral ligaments tear in sequence from front to back: first the anterior talofibular, then the calcaneofibular. The posterior talofibular is the strongest and tears only in severe injuries."),
  ("Quel ligament latéral de la cheville est le plus solide et se rompt le moins souvent ?", ["Ligament bifurqué", "Ligament talo-fibulaire postérieur", "Ligament talo-fibulaire antérieur", "Ligament calcanéo-fibulaire", "Ligament tibio-fibulaire antérieur"],
   "Les ligaments latéraux se rompent d'avant en arrière : d'abord le talo-fibulaire antérieur, puis le calcanéo-fibulaire. Le talo-fibulaire postérieur est le plus solide et ne cède que dans les traumatismes graves."),
  ("Welches Außenband des Sprunggelenks ist am stärksten und reißt am seltensten?", ["Lig. bifurcatum", "Lig. talofibulare posterius", "Lig. talofibulare anterius", "Lig. calcaneofibulare", "Lig. tibiofibulare anterius"],
   "Die Außenbänder reißen von vorn nach hinten: zuerst das Lig. talofibulare anterius, dann das Lig. calcaneofibulare. Das Lig. talofibulare posterius ist am stärksten und reißt nur bei schweren Verletzungen."),
  ("¿Qué ligamento lateral del tobillo es el más fuerte y se rompe con menos frecuencia?", ["Ligamento bifurcado", "Ligamento peroneoastragalino posterior", "Ligamento peroneoastragalino anterior", "Ligamento peroneocalcáneo", "Ligamento tibioperoneo anterior"],
   "Los ligamentos laterales se rompen de delante atrás: primero el peroneoastragalino anterior y luego el peroneocalcáneo. El peroneoastragalino posterior es el más fuerte y solo se rompe en lesiones graves."))

T("ar-b878c17d",
  ("Which ligament does the anterior drawer test of the ankle mainly assess?", ["Calcaneofibular ligament", "Deltoid ligament", "Posterior talofibular ligament", "Syndesmotic ligaments", "Anterior talofibular ligament"],
   "In the anterior drawer test the tibia is fixed and the heel pulled forwards; forward sliding of the talus indicates a tear of the anterior talofibular ligament. The calcaneofibular ligament is assessed with the talar tilt (inversion stress) test."),
  ("Quel ligament le test du tiroir antérieur de la cheville évalue-t-il principalement ?", ["Ligament calcanéo-fibulaire", "Ligament deltoïde", "Ligament talo-fibulaire postérieur", "Ligaments de la syndesmose", "Ligament talo-fibulaire antérieur"],
   "Dans le tiroir antérieur, on fixe le tibia et on tire le talon vers l'avant ; la translation antérieure du talus indique une rupture du talo-fibulaire antérieur. Le calcanéo-fibulaire s'évalue par le test du bâillement talien (varus forcé)."),
  ("Welches Band prüft der vordere Schubladentest am Sprunggelenk hauptsächlich?", ["Lig. calcaneofibulare", "Lig. deltoideum", "Lig. talofibulare posterius", "Syndesmosebänder", "Lig. talofibulare anterius"],
   "Beim vorderen Schubladentest wird die Tibia fixiert und die Ferse nach vorn gezogen; ein Vorgleiten des Talus spricht für einen Riss des Lig. talofibulare anterius. Das Lig. calcaneofibulare wird mit dem Talar-Tilt-Test (Inversionsstress) geprüft."),
  ("¿Qué ligamento valora principalmente la prueba del cajón anterior del tobillo?", ["Ligamento peroneocalcáneo", "Ligamento deltoideo", "Ligamento peroneoastragalino posterior", "Ligamentos de la sindesmosis", "Ligamento peroneoastragalino anterior"],
   "En el cajón anterior se fija la tibia y se tracciona el talón hacia delante; el desplazamiento anterior del astrágalo indica rotura del peroneoastragalino anterior. El peroneocalcáneo se valora con la prueba de inclinación astragalina (estrés en inversión)."))

T("ar-47535364",
  ("Which structures are injured in a high ankle sprain?", ["Distal tibiofibular syndesmotic ligaments", "Achilles tendon", "Lisfranc ligament", "Deltoid ligament", "Lateral collateral ligaments of the ankle"],
   "A high ankle sprain usually occurs with external rotation and tears the syndesmotic ligaments joining the tibia and fibula; it takes much longer to heal than a lateral ligament sprain."),
  ("Quelles structures sont lésées dans l'entorse haute de la cheville ?", ["Ligaments de la syndesmose tibio-fibulaire distale", "Tendon calcanéen (d'Achille)", "Ligament de Lisfranc", "Ligament deltoïde", "Ligaments collatéraux latéraux de la cheville"],
   "L'entorse haute survient le plus souvent en rotation externe et rompt les ligaments de la syndesmose unissant tibia et fibula ; sa guérison est bien plus longue que celle d'une entorse latérale."),
  ("Welche Strukturen sind bei der hohen Sprunggelenksverstauchung verletzt?", ["Bänder der distalen tibiofibularen Syndesmose", "Achillessehne", "Lisfranc-Band", "Lig. deltoideum", "Außenbänder des Sprunggelenks"],
   "Die hohe Sprunggelenksverstauchung entsteht meist durch Außenrotation und zerreißt die Syndesmosebänder zwischen Tibia und Fibula; sie heilt deutlich langsamer als eine Außenbandverletzung."),
  ("¿Qué estructuras se lesionan en el esguince alto de tobillo?", ["Ligamentos de la sindesmosis tibioperonea distal", "Tendón de Aquiles", "Ligamento de Lisfranc", "Ligamento deltoideo", "Ligamentos colaterales laterales del tobillo"],
   "El esguince alto suele producirse con rotación externa y rompe los ligamentos de la sindesmosis que unen tibia y peroné; tarda mucho más en curar que un esguince del ligamento lateral."))

T("ar-f12bf4cd",
  ("Which structure, located in the sinus tarsi, is the strongest ligament of the subtalar joint?", ["Long plantar ligament", "Lateral talocalcaneal ligament", "Bifurcate ligament", "Calcaneofibular ligament", "Interosseous talocalcaneal ligament"],
   "The interosseous talocalcaneal ligament lies in the sinus tarsi between the talus and calcaneus and is the main ligament of the subtalar joint."),
  ("Quelle structure, située dans le sinus du tarse, est le ligament le plus solide de l'articulation sous-talienne ?", ["Ligament plantaire long", "Ligament talo-calcanéen latéral", "Ligament bifurqué", "Ligament calcanéo-fibulaire", "Ligament talo-calcanéen interosseux"],
   "Le ligament talo-calcanéen interosseux occupe le sinus du tarse entre talus et calcanéus ; c'est le ligament principal de la sous-talienne."),
  ("Welche im Sinus tarsi gelegene Struktur ist das stärkste Band des unteren Sprunggelenks?", ["Lig. plantare longum", "Lig. talocalcaneum laterale", "Lig. bifurcatum", "Lig. calcaneofibulare", "Lig. talocalcaneum interosseum"],
   "Das Lig. talocalcaneum interosseum liegt im Sinus tarsi zwischen Talus und Calcaneus und ist das Hauptband des unteren Sprunggelenks."),
  ("¿Qué estructura, situada en el seno del tarso, es el ligamento más fuerte de la articulación subastragalina?", ["Ligamento plantar largo", "Ligamento astragalocalcáneo lateral", "Ligamento bifurcado", "Ligamento peroneocalcáneo", "Ligamento astragalocalcáneo interóseo"],
   "El ligamento astragalocalcáneo interóseo ocupa el seno del tarso entre astrágalo y calcáneo y es el ligamento principal de la subastragalina."))

T("ar-d75092b5",
  ("Which joints make up Chopart's (transverse tarsal) joint?", ["Cuneonavicular and intercuneiform joints", "Calcaneocuboid and cuboideonavicular joints", "Tarsometatarsal and intermetatarsal joints", "Talocrural and subtalar joints", "Talonavicular and calcaneocuboid joints"],
   "Chopart's joint is the S-shaped joint line between the hindfoot and midfoot and is one of the amputation levels. Lisfranc's joint is the tarsometatarsal joints."),
  ("Quelles articulations composent l'interligne de Chopart (transverse du tarse) ?", ["Cunéo-naviculaire et intercunéennes", "Calcanéo-cuboïdienne et cuboïdo-naviculaire", "Tarso-métatarsiennes et intermétatarsiennes", "Talo-crurale et sous-talienne", "Talo-naviculaire et calcanéo-cuboïdienne"],
   "L'interligne de Chopart est la ligne articulaire en S entre arrière-pied et médio-pied ; c'est un niveau d'amputation. L'interligne de Lisfranc correspond aux tarso-métatarsiennes."),
  ("Welche Gelenke bilden die Chopart-Gelenklinie (Art. tarsi transversa)?", ["Art. cuneonavicularis und Interkuneiformgelenke", "Art. calcaneocuboidea und Art. cuboideonavicularis", "Tarsometatarsal- und Intermetatarsalgelenke", "Oberes und unteres Sprunggelenk", "Art. talonavicularis und Art. calcaneocuboidea"],
   "Die Chopart-Linie ist die S-förmige Gelenklinie zwischen Rück- und Mittelfuß und eine Amputationshöhe. Die Lisfranc-Linie entspricht den Tarsometatarsalgelenken."),
  ("¿Qué articulaciones forman la articulación de Chopart (transversa del tarso)?", ["Cuneonavicular e intercuneiformes", "Calcaneocuboidea y cuboideonavicular", "Tarsometatarsianas e intermetatarsianas", "Talocrural y subastragalina", "Astragaloescafoidea y calcaneocuboidea"],
   "La articulación de Chopart es la línea articular en S entre retropié y mediopié y es un nivel de amputación. La de Lisfranc corresponde a las tarsometatarsianas."))

T("ar-a378349f",
  ("Where does the Lisfranc ligament run?", ["From the navicular to the medial cuneiform", "From the calcaneus to the cuboid", "From the intermediate cuneiform to the base of the 2nd metatarsal", "From the cuboid to the base of the 5th metatarsal", "From the medial cuneiform to the base of the 2nd metatarsal"],
   "The Lisfranc ligament is a strong interosseous ligament between the medial cuneiform and the base of the 2nd metatarsal; since there is no ligament between the bases of the 1st and 2nd metatarsals, it is the key to the tarsometatarsal joint."),
  ("Où s'étend le ligament de Lisfranc ?", ["Du naviculaire au cunéiforme médial", "Du calcanéus au cuboïde", "Du cunéiforme intermédiaire à la base du 2e métatarsien", "Du cuboïde à la base du 5e métatarsien", "Du cunéiforme médial à la base du 2e métatarsien"],
   "Le ligament de Lisfranc est un puissant ligament interosseux entre le cunéiforme médial et la base du 2e métatarsien ; comme il n'existe pas de ligament entre les bases des 1er et 2e métatarsiens, il est la clé de l'interligne tarso-métatarsien."),
  ("Wo verläuft das Lisfranc-Band?", ["Vom Os naviculare zum inneren Keilbein", "Vom Calcaneus zum Würfelbein", "Vom mittleren Keilbein zur Basis des 2. Mittelfußknochens", "Vom Würfelbein zur Basis des 5. Mittelfußknochens", "Vom inneren Keilbein zur Basis des 2. Mittelfußknochens"],
   "Das Lisfranc-Band ist ein kräftiges interossäres Band zwischen innerem Keilbein und Basis des 2. Mittelfußknochens; da zwischen den Basen des 1. und 2. Mittelfußknochens kein Band besteht, ist es der Schlüssel des Tarsometatarsalgelenks."),
  ("¿Por dónde se extiende el ligamento de Lisfranc?", ["Del navicular a la cuña medial", "Del calcáneo al cuboides", "De la cuña intermedia a la base del 2.º metatarsiano", "Del cuboides a la base del 5.º metatarsiano", "De la cuña medial a la base del 2.º metatarsiano"],
   "El ligamento de Lisfranc es un potente ligamento interóseo entre la cuña medial y la base del 2.º metatarsiano; como no hay ligamento entre las bases del 1.º y 2.º metatarsianos, es la clave de la articulación tarsometatarsiana."))
